def validar_key(key: str):
    cleaned = key.strip().upper().replace("-", "").replace(" ", "")
    if len(cleaned) != 16:
        return None
    data, sig = cleaned[:8], cleaned[8:]
    expected = hmac.new(LICENSE_SECRET.encode(), data.encode(), hashlib.sha256).hexdigest()[:8].upper()
    if not hmac.compare_digest(sig, expected):
        return None
    try:
        return int(data, 36)
    except ValueError:
        return None


def carregar_licenca():
    try:
        with open(LICENSE_FILE, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None


def salvar_licenca(key, expiry):
    try:
        with open(LICENSE_FILE, "w", encoding="utf-8") as f:
            json.dump({"key": key, "expiry": expiry}, f)
    except Exception:
        pass


class LicenseGate(tk.Tk):
    def __init__(self):
        super().__init__()
        self.title("Ativação - " + APP_NAME)
        self.configure(bg=BG)
        self.geometry("380x380")
        self.resizable(False, False)
        self.aprovado = False

        self.logo_medium = tk.PhotoImage(data=LOGO_MEDIUM_B64)
        tk.Label(self, image=self.logo_medium, bg=BG).pack(pady=(20, 6))

        tk.Label(self, text=APP_NAME, bg=BG, fg=BLUE,
                  font=("Segoe UI", 14, "bold")).pack(pady=(0, 4))
        tk.Label(self, text="Digite sua chave de licença", bg=BG, fg=TEXT_DIM,
                  font=("Segoe UI", 9)).pack(pady=(0, 14))

        self.entry = tk.Entry(self, font=("Consolas", 13), justify="center",
                               bg=PANEL, fg=TEXT, insertbackground=TEXT, relief="flat")
        self.entry.pack(ipady=8, padx=30, fill="x")
        self.entry.focus()
        self.entry.bind("<Return>", lambda e: self._validar())

        self.status = tk.Label(self, text="", bg=BG, fg=BLUE, font=("Segoe UI", 9))
        self.status.pack(pady=10)

        tk.Button(self, text="Ativar", command=self._validar, bg=BLUE, fg="white",
                   relief="flat", font=("Segoe UI", 10, "bold"), padx=20, pady=6,
                   cursor="hand2").pack()

    def _validar(self):
        expiry = validar_key(self.entry.get())
        if expiry is None:
            self.status.config(text="Chave inválida.", fg="#ff6b6b")
            return
        if expiry <= time.time():
            self.status.config(text="Essa chave já expirou.", fg="#ff6b6b")
            return
        salvar_licenca(self.entry.get().strip().upper(), expiry)
        self.aprovado = True
        self.destroy()


def checar_licenca():
    salva = carregar_licenca()
    if salva and salva.get("expiry", 0) > time.time():
        return salva
    gate = LicenseGate()
    gate.mainloop()
    return carregar_licenca() if gate.aprovado else None


def is_admin() -> bool:
    if not IS_WINDOWS:
        return False
    try:
        return bool(ctypes.windll.shell32.IsUserAnAdmin())
    except Exception:
        return False


def relaunch_as_admin():
    ctypes.windll.shell32.ShellExecuteW(
        None, "runas", sys.executable, " ".join(f'"{a}"' for a in sys.argv), None, 1
    )
    sys.exit(0)


# ---------------------------------------------------------------
# Atualização automática
# ---------------------------------------------------------------
UPDATE_FILE = "painel_otimizacao.py"
UPDATE_MANIFEST = "version.json"
_SECRET_RE = re.compile(r'^LICENSE_SECRET\s*=\s*".*"\s*$', re.M)
_VERSION_RE = re.compile(r'^APP_VERSION\s*=\s*"([^"]+)"', re.M)


def _update_configurado() -> bool:
    return "SEU_USUARIO" not in UPDATE_BASE_URL and UPDATE_BASE_URL.startswith("https://")


def _ver_tuple(v):
    try:
        return tuple(int(x) for x in str(v).strip().split("."))
    except ValueError:
        return (0,)


def _http_get(url: str, timeout: int = 15) -> bytes:
    req = urllib.request.Request(url, headers={"User-Agent": "THzx-Optimizer", "Cache-Control": "no-cache"})
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return resp.read()


def _assinar_update(version: str, sha256: str) -> str:
    msg = f"{version}|{sha256}".encode()
    return hmac.new(LICENSE_SECRET.encode(), msg, hashlib.sha256).hexdigest()


def verificar_update():
    # Retorna None se já está na versão mais recente, ou {"version", "sha256"} se há versão nova.
    base = UPDATE_BASE_URL.rstrip("/")
    man = json.loads(_http_get(f"{base}/{UPDATE_MANIFEST}").decode("utf-8"))
    version = str(man["version"]).strip()
    sha = str(man["sha256"]).strip().lower()
    sig = str(man["sig"]).strip().lower()
    if not hmac.compare_digest(sig, _assinar_update(version, sha)):
        raise ValueError("Assinatura da atualização inválida. Ignorada por segurança.")
    if _ver_tuple(version) <= _ver_tuple(APP_VERSION):
        return None
    return {"version": version, "sha256": sha}


def baixar_e_instalar(man):
    if getattr(sys, "frozen", False):
        raise RuntimeError("Este programa está empacotado (.exe). A atualização automática só funciona com o arquivo .py.")
    destino = os.path.abspath(sys.argv[0])
    if not destino.lower().endswith(".py"):
        raise RuntimeError("Não foi possível localizar o arquivo .py do programa para atualizar.")

    base = UPDATE_BASE_URL.rstrip("/")
    dados = _http_get(f"{base}/{UPDATE_FILE}", timeout=60).replace(b"\r\n", b"\n")
    if hashlib.sha256(dados).hexdigest() != man["sha256"]:
        raise ValueError("O arquivo baixado não confere com a assinatura (corrompido ou adulterado).")

    texto = dados.decode("utf-8")
    achou = _VERSION_RE.search(texto)
    if not achou or achou.group(1) != man["version"]:
        raise ValueError("A versão dentro do arquivo não bate com a versão anunciada.")

    # O arquivo publicado não leva o seu segredo: reaproveita o que já está neste PC.
    texto = _SECRET_RE.sub(lambda _m: "LICENSE_SECRET = " + json.dumps(LICENSE_SECRET), texto, count=1)
    compile(texto, UPDATE_FILE, "exec")  # garante que o código novo não tem erro de sintaxe

    tmp = destino + ".novo"
    with open(tmp, "w", encoding="utf-8", newline="\n") as f:
        f.write(texto)
    shutil.copy2(destino, destino + ".bak")  # cópia de segurança da versão atual
    os.replace(tmp, destino)


def load_state() -> dict:
    try:
        with open(STATE_FILE, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return {}


def save_state(state: dict):
    try:
        with open(STATE_FILE, "w", encoding="utf-8") as f:
            json.dump(state, f, ensure_ascii=False, indent=2)
    except Exception:
        pass


# ---------------------------------------------------------------
# Informações do PC (CPU, GPU, RAM, disco, SO)
# ---------------------------------------------------------------
def _run_ps(cmd: str):
    try:
        out = subprocess.run(["powershell", "-NoProfile", "-Command", cmd],
                              capture_output=True, text=True, timeout=6)
        value = out.stdout.strip()
        return value if value else None
    except Exception:
        return None


def get_system_info() -> dict:
    info = {
        "cpu": None, "gpu": None, "ram_total_gb": None, "ram_used_pct": None,
        "disk_total_gb": None, "disk_used_pct": None, "os": None,
    }

    if IS_WINDOWS:
        info["cpu"] = _run_ps("(Get-CimInstance Win32_Processor).Name")
        gpu_raw = _run_ps("(Get-CimInstance Win32_VideoController).Name")
        if gpu_raw:
            # pode vir mais de uma linha se houver GPU integrada + dedicada
            info["gpu"] = " / ".join(l.strip() for l in gpu_raw.splitlines() if l.strip())
        total_kb = _run_ps("(Get-CimInstance Win32_OperatingSystem).TotalVisibleMemorySize")
        free_kb = _run_ps("(Get-CimInstance Win32_OperatingSystem).FreePhysicalMemory")
        try:
            total_kb, free_kb = int(total_kb), int(free_kb)
            info["ram_total_gb"] = round(total_kb * 1024 / 1e9, 1)
            info["ram_used_pct"] = round((1 - free_kb / total_kb) * 100)
        except (TypeError, ValueError):
            pass
        build = _run_ps("(Get-CimInstance Win32_OperatingSystem).Caption")
        info["os"] = build
    else:
        info["cpu"] = platform.processor() or platform.machine()
        info["os"] = platform.platform()

    try:
        drive = "C:\\" if IS_WINDOWS else "/"
        total, used, _free = shutil.disk_usage(drive)
        info["disk_total_gb"] = round(total / (1024 ** 3), 1)
        info["disk_used_pct"] = round(used / total * 100)
    except Exception:
        pass

    for key in ("cpu", "gpu", "os"):
        if not info[key]:
            info[key] = "Não foi possível identificar"
    return info


class ToggleSwitch(tk.Canvas):
    def __init__(self, master, value=False, command=None, color=BLUE, **kw):
        super().__init__(master, width=42, height=22, bg=PANEL,
                          highlightthickness=0, cursor="hand2", **kw)
        self.color = color
        self.value = value
        self.command = command
        self.bind("<Button-1>", self._toggle)
        self._draw()

    def _toggle(self, _event=None):
        self.value = not self.value
        self._draw()
        if self.command:
            self.command(self.value)

    def set(self, value):
        self.value = value
        self._draw()

    def _draw(self):
        self.delete("all")
        track = self.color if self.value else LINE
        self.create_oval(2, 2, 20, 20, fill=track, outline="")
        self.create_oval(22, 2, 40, 20, fill=track, outline="")
        self.create_rectangle(11, 2, 31, 20, fill=track, outline="")
        cx = 31 if self.value else 11
        self.create_oval(cx - 8, 3, cx + 8, 19, fill="#ffffff" if self.value else "#5d6684", outline="")


class App(tk.Tk):
    def __init__(self, licenca):
        super().__init__()
        self.licenca = licenca
        self.title(APP_NAME)
        self.configure(bg=BG)
        self.geometry("1000x650")
        self.minsize(880, 560)

        self.state_data = load_state()
        self.sysinfo = get_system_info()
        self.switches = {}      # label -> ToggleSwitch
        self.info_frames = {}   # (page_key,label) -> frame
        self.page_frames = {}
        self.sidebar_buttons = {}
        self.current_page = "Dashboard"

        self._build_sidebar()
        self._build_main()
        self._build_status_panel()
        self._show_page("Dashboard")
        if _update_configurado():
            self.after(2000, lambda: self._checar_update(manual=False))

        if not IS_WINDOWS:
            messagebox.showinfo(APP_NAME, "Sistema não-Windows: os comandos serão simulados, sem executar de verdade.")

    # ---------------- Sidebar ----------------
    def _build_sidebar(self):
        bar = tk.Frame(self, bg=SIDEBAR_BG, width=210)
        bar.pack(side="left", fill="y")
        bar.pack_propagate(False)

        header = tk.Frame(bar, bg=SIDEBAR_BG)
        header.pack(fill="x", pady=(18, 20), padx=12)
        self.logo_small = tk.PhotoImage(data=LOGO_SMALL_B64)
        tk.Label(header, image=self.logo_small, bg=SIDEBAR_BG).pack(anchor="center")
        tk.Label(header, text=APP_NAME, bg=SIDEBAR_BG, fg=TEXT, font=("Segoe UI", 10, "bold"),
                  wraplength=186, justify="center", anchor="center").pack(fill="x", pady=(6, 0))

        for page in PAGES:
            danger = page in DANGER_PAGES
            btn = tk.Button(bar, text=f"  {PAGE_ICONS[page]}  {page}", anchor="w",
                              bg=SIDEBAR_BG, fg=RED_DIM if danger else TEXT_DIM, relief="flat", bd=0,
                              font=("Segoe UI", 10, "bold" if danger else "normal"),
                              padx=10, pady=10, cursor="hand2",
                              activebackground=RED_BG if danger else SIDEBAR_ACTIVE,
                              activeforeground=RED if danger else TEXT,
                              command=lambda p=page: self._show_page(p))
            btn.pack(fill="x", padx=8, pady=(10, 1) if danger else 1)
            self.sidebar_buttons[page] = btn

    def _highlight_sidebar(self, page):
        for p, btn in self.sidebar_buttons.items():
            danger = p in DANGER_PAGES
            if p == page:
                btn.configure(bg=RED_BG if danger else SIDEBAR_ACTIVE, fg=RED if danger else TEXT)
            else:
                btn.configure(bg=SIDEBAR_BG, fg=RED_DIM if danger else TEXT_DIM)

    # ---------------- Main content ----------------
    def _build_main(self):
        self.main = tk.Frame(self, bg=BG)
        self.main.pack(side="left", fill="both", expand=True)

        header_row = tk.Frame(self.main, bg=BG)
        header_row.pack(fill="x", padx=22, pady=(20, 14))

        header_left = tk.Frame(header_row, bg=BG)
        header_left.pack(side="left", fill="x", expand=True)
        self.header_title = tk.Label(header_left, text="", bg=BG, fg=TEXT, font=("Segoe UI", 16, "bold"))
        self.header_title.pack(anchor="w")
        self.header_subtitle = tk.Label(header_left, text="", bg=BG, fg=TEXT_DIM, font=("Segoe UI", 9))
        self.header_subtitle.pack(anchor="w", pady=(2, 0))

        self.header_right = tk.Frame(header_row, bg=BG)
        self.header_right.pack(side="right")

        self.content_host = tk.Frame(self.main, bg=BG)
        self.content_host.pack(fill="both", expand=True, padx=22)

        for page in PAGES:
            self.page_frames[page] = self._build_page(self.content_host, page)

    def _build_page(self, parent, page):
        frame = tk.Frame(parent, bg=BG)
        if page == "Dashboard":
            self._fill_dashboard(frame)
        elif page == "Configurações":
            self._fill_settings(frame)
        else:
            danger = page in DANGER_PAGES
            items = [t for t in TWEAKS
                     if (page == "Otimizações" and t["page"] not in DANGER_PAGES) or t["page"] == page]
            self._fill_items_list(frame, items, show_apply_all=not danger, danger=danger)
        return frame

    def _make_scrollable(self, parent, content_width=560):
        """Canvas com scrollbar escura (combinando com o tema) e scroll do mouse funcionando."""
        style = ttk.Style(self)
        try:
            style.theme_use("clam")
        except tk.TclError:
            pass
        style.configure("Dark.Vertical.TScrollbar", background=PANEL2, troughcolor=BG,
                          bordercolor=BG, arrowcolor=TEXT_DIM, relief="flat", arrowsize=12, width=10)
        style.map("Dark.Vertical.TScrollbar", background=[("active", LINE)])

        canvas = tk.Canvas(parent, bg=BG, highlightthickness=0)
        scrollbar = ttk.Scrollbar(parent, orient="vertical", command=canvas.yview,
                                    style="Dark.Vertical.TScrollbar")
        inner = tk.Frame(canvas, bg=BG)
        inner.bind("<Configure>", lambda e: canvas.configure(scrollregion=canvas.bbox("all")))
        canvas.create_window((0, 0), window=inner, anchor="nw", width=content_width)
        canvas.configure(yscrollcommand=scrollbar.set)
        canvas.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")

        def _on_mousewheel(event):
            canvas.yview_scroll(int(-1 * (event.delta / 120)), "units")

        def _bind_wheel(_e):
            canvas.bind_all("<MouseWheel>", _on_mousewheel)

        def _unbind_wheel(_e):
            canvas.unbind_all("<MouseWheel>")

        canvas.bind("<Enter>", _bind_wheel)
        canvas.bind("<Leave>", _unbind_wheel)
        inner.bind("<Enter>", _bind_wheel)

        return canvas, inner

    def _fill_items_list(self, frame, items, show_apply_all=False, danger=False):
        canvas, inner = self._make_scrollable(frame)

        if danger:
            warn = tk.Frame(inner, bg=RED_BG, highlightbackground=RED, highlightthickness=1)
            warn.pack(fill="x", pady=(0, 10))
            tk.Label(warn, text="⚠️ ZONA DE RISCO", bg=RED_BG, fg=RED,
                      font=("Segoe UI", 11, "bold")).pack(anchor="w", padx=14, pady=(12, 2))
            tk.Label(warn, text="Estes ajustes reduzem segurança ou desligam recursos do Windows em troca de "
                                "desempenho. Crie um ponto de restauração antes, abra o programa como "
                                "administrador e reinicie o PC depois de aplicar.",
                      bg=RED_BG, fg=TEXT_DIM, font=("Segoe UI", 9), wraplength=500, justify="left") \
                .pack(anchor="w", padx=14, pady=(0, 12))

        if show_apply_all:
            top = tk.Frame(inner, bg=PANEL, highlightbackground=LINE, highlightthickness=1)
            top.pack(fill="x", pady=(0, 10))
            tk.Label(top, text="⚡ Otimizações rápidas", bg=PANEL, fg=TEXT,
                      font=("Segoe UI", 11, "bold")).pack(side="left", padx=14, pady=14)
            tk.Button(top, text="✓ Aplicar tudo", command=lambda its=items: self._apply_all(its),
                       bg=BLUE, fg="white", relief="flat", font=("Segoe UI", 9, "bold"),
                       padx=14, pady=6, cursor="hand2").pack(side="right", padx=14)

        card = tk.Frame(inner, bg=PANEL, highlightbackground=RED_LINE if danger else LINE,
                         highlightthickness=1)
        card.pack(fill="x")
        for i, item in enumerate(items):
            self._build_item_row(card, item, border=(i != 0), danger=danger)

    def _build_item_row(self, parent, item, border=True, danger=False):
        accent = RED if danger else BLUE
        wrap = tk.Frame(parent, bg=PANEL)
        wrap.pack(fill="x")
        if border:
            tk.Frame(wrap, bg=RED_LINE if danger else LINE, height=1).pack(fill="x")

        row = tk.Frame(wrap, bg=PANEL)
        row.pack(fill="x", padx=16, pady=12)

        tk.Label(row, text=item["icon"], bg=PANEL, font=("Segoe UI Emoji", 14)).pack(side="left", padx=(0, 12))

        mid = tk.Frame(row, bg=PANEL)
        mid.pack(side="left", fill="x", expand=True)
        title_txt = item["label"] + ("  [admin]" if item.get("admin") else "")
        tk.Label(mid, text=title_txt, bg=PANEL, fg=TEXT, font=("Segoe UI", 10, "bold"),
                  anchor="w").pack(fill="x")
        tk.Label(mid, text=item["desc"], bg=PANEL, fg=TEXT_DIM, font=("Segoe UI", 9),
                  anchor="w").pack(fill="x")

        key = item["label"]
        chevron = tk.Button(row, text="›", bg=PANEL, fg=TEXT_DIM, relief="flat", bd=0,
                              font=("Segoe UI", 13), cursor="hand2", activebackground=PANEL,
                              command=lambda: self._toggle_info(key))
        chevron.pack(side="left", padx=(6, 10))

        if item["type"] == "toggle":
            sw = ToggleSwitch(row, value=bool(self.state_data.get(key, False)), color=accent,
                               command=lambda v, it=item: self._on_toggle(it, v))
            sw.pack(side="right")
            self.switches[key] = sw
        else:
            tk.Button(row, text="Executar", command=lambda it=item: self._on_toggle(it, True),
                       bg=RED if danger else PANEL2, fg="white" if danger else TEXT, relief="flat",
                       font=("Segoe UI", 9), padx=10, pady=5, cursor="hand2").pack(side="right")

        info_bg = RED_BG if danger else PANEL2
        info_frame = tk.Frame(wrap, bg=info_bg)
