        for w in self.bars_host.winfo_children():
            w.destroy()

        groups = [("Sistema", "Sistema"), ("Jogos", "Jogos"), ("Resposta", "Taxa de Resposta"),
                  ("Privacidade", "Privacidade"), ("Debloat", "Debloat Agressivo")]
